package ama.api;
import ama.contract.GovernanceContracts.*;
import ama.contract.IdentityContracts.*;
import ama.governance.JdbcGovernanceWorkbench;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@ConditionalOnProperty(name="operations.enabled",havingValue="true")
class GovernanceWorkbenchController {
 private final JdbcGovernanceWorkbench workbench;
 private final ObjectMapper json=new ObjectMapper(JsonFactory.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(StreamReadConstraints.builder().maxStringLength(65536).maxNestingDepth(16).build()).build()).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
 GovernanceWorkbenchController(JdbcGovernanceWorkbench workbench){this.workbench=workbench;}
 @GetMapping("/api/v1/operations/catalog") ResponseEntity<?> catalog(HttpServletRequest r){noQuery(r);return ok(workbench.catalog(actor(r)));}
 @GetMapping({"/api/v1/operations/configuration/history","/api/v1/operations/candidates/{candidate}/history"}) ResponseEntity<?> history(@PathVariable(required=false) String candidate,HttpServletRequest r){for(var e:r.getParameterMap().entrySet())if(!Set.of("cursor","limit").contains(e.getKey())||e.getValue().length!=1)throw new IllegalArgumentException("Exact history query required");int limit=20;try{if(r.getParameter("limit")!=null)limit=Integer.parseInt(r.getParameter("limit"));}catch(NumberFormatException bad){throw new IllegalArgumentException("Page limit required");}return ok(workbench.historyPage(actor(r),candidate,r.getParameter("cursor"),limit));}
 @GetMapping("/api/v1/meetings/{id}/speaker-candidates") ResponseEntity<?> speakerCandidates(@PathVariable String id,HttpServletRequest r){noQuery(r);return ok(workbench.meetingContext(actor(r),id));}
 @GetMapping("/api/v1/operations/{module}/page") ResponseEntity<?> page(@PathVariable String module,HttpServletRequest r){for(var e:r.getParameterMap().entrySet())if(!Set.of("cursor","q","state","limit","type","usage","model","from","to").contains(e.getKey())||e.getValue().length!=1)throw new IllegalArgumentException("Exact page filters required");int limit=20;try{if(r.getParameter("limit")!=null)limit=Integer.parseInt(r.getParameter("limit"));}catch(NumberFormatException bad){throw new IllegalArgumentException("Page limit required");}var filters=new LinkedHashMap<String,String>();for(String name:List.of("type","usage","model","from","to"))if(r.getParameter(name)!=null)filters.put(name,r.getParameter(name));return ok(workbench.page(actor(r),module,r.getParameter("cursor"),r.getParameter("q"),r.getParameter("state"),limit,filters));}
 @PostMapping(value="/api/v1/operations/sample-assets",consumes="audio/wav") ResponseEntity<?> asset(@RequestBody byte[] bytes,HttpServletRequest r){noQuery(r);if(bytes.length>3840044)throw new OperationsController.TooLarge();String name=r.getHeader("X-Sample-Name");if(name==null)throw new IllegalArgumentException("Sample name required");try{name=java.net.URLDecoder.decode(name,java.nio.charset.StandardCharsets.UTF_8);}catch(IllegalArgumentException bad){throw new IllegalArgumentException("Encoded sample name required");}return ok(workbench.upload(actor(r),key(r),name,bytes));}
 @GetMapping("/api/v1/operations/datasets/{id}") ResponseEntity<?> dataset(@PathVariable String id,HttpServletRequest r){noQuery(r);return ok(workbench.datasetDetail(actor(r),id));}
 @PostMapping("/api/v1/operations/datasets/{id}/copies") ResponseEntity<?> copy(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"version");return ok(workbench.copyDataset(actor(r),id,key(r),text(b,"version")));}
 @GetMapping("/api/v1/operations/reports/{id}") ResponseEntity<?> report(@PathVariable String id,HttpServletRequest r){noQuery(r);return ok(workbench.report(actor(r),id));}
 @GetMapping("/api/v1/operations/voiceprints/{id}") ResponseEntity<?> voice(@PathVariable String id,HttpServletRequest r){noQuery(r);return ok(workbench.voiceDetail(actor(r),id));}
 @PostMapping("/api/v1/operations/evaluations/{id}/cancellation") ResponseEntity<?> cancel(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"reason");return ok(workbench.cancel(actor(r),id,key(r),text(b,"reason")));}
 @PostMapping("/api/v1/operations/evaluations/{id}/retries") ResponseEntity<?> retry(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest r){body(bytes);return ok(workbench.retry(actor(r),id,key(r)));}
 @PostMapping("/api/v1/operations/evaluations/{id}/samples/{sample}/review") ResponseEntity<?> review(@PathVariable String id,@PathVariable String sample,@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"rubric","reason");var rubric=new LinkedHashMap<String,Double>();var node=b.get("rubric");if(!node.isObject())throw new IllegalArgumentException("Rubric required");node.fields().forEachRemaining(e->{if(!e.getValue().isNumber())throw new IllegalArgumentException("Numeric rubric required");rubric.put(e.getKey(),e.getValue().doubleValue());});return ok(workbench.reviewSample(actor(r),id,sample,key(r),rubric,text(b,"reason")));}
 @PostMapping("/api/v1/operations/candidates") ResponseEntity<?> create(@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"title","configuration","rules","reason");return ok(workbench.saveCandidate(actor(r),null,key(r),0,text(b,"title"),convert(b,"configuration",ModelConfig.class),convert(b,"rules",QualificationRules.class),text(b,"reason")));}
 @GetMapping("/api/v1/operations/candidates/{id}") ResponseEntity<?> candidate(@PathVariable String id,HttpServletRequest r){noQuery(r);return ok(workbench.candidate(actor(r),id));}
 @PostMapping("/api/v1/operations/candidates/{id}/edits") ResponseEntity<?> edit(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"expectedRevisionToken","title","configuration","rules","reason");return ok(workbench.saveCandidate(actor(r),id,key(r),revision(b,"expectedRevisionToken"),text(b,"title"),convert(b,"configuration",ModelConfig.class),convert(b,"rules",QualificationRules.class),text(b,"reason")));}
 @PostMapping("/api/v1/operations/candidates/{id}/evaluations") ResponseEntity<?> evaluate(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"expectedRevisionToken","datasetId");return ok(workbench.evaluateCandidate(actor(r),id,key(r),revision(b,"expectedRevisionToken"),text(b,"datasetId")));}
 @PostMapping("/api/v1/operations/candidates/{id}/approval") ResponseEntity<?> approve(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"expectedRevisionToken","evaluationId","reason");return ok(workbench.approveCandidate(actor(r),id,key(r),revision(b,"expectedRevisionToken"),text(b,"evaluationId"),text(b,"reason")));}
 @PostMapping("/api/v1/operations/candidates/{id}/publication") ResponseEntity<?> publish(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"expectedRevisionToken","currentConfigurationRevisionToken","reason");return ok(workbench.publishCandidate(actor(r),id,key(r),revision(b,"expectedRevisionToken"),revision(b,"currentConfigurationRevisionToken"),text(b,"reason")));}
 @PostMapping("/api/v1/operations/rollback-candidates") ResponseEntity<?> rollback(@RequestBody byte[] bytes,HttpServletRequest r){var b=body(bytes,"targetRevisionToken","title","reason","rules");return ok(workbench.rollbackCandidate(actor(r),key(r),revision(b,"targetRevisionToken"),text(b,"title"),text(b,"reason"),convert(b,"rules",QualificationRules.class)));}
 private <T>T convert(JsonNode node,String key,Class<T> type){try{return json.treeToValue(node.get(key),type);}catch(JsonProcessingException bad){throw new IllegalArgumentException("Exact bounded configuration required");}}
 private JsonNode body(byte[] bytes,String... fields){if(bytes.length>131072)throw new OperationsController.TooLarge();try{var b=json.readTree(bytes);var allowed=Set.of(fields);if(b==null||!b.isObject()||b.size()!=allowed.size())throw new IllegalArgumentException("Exact fields required");b.fieldNames().forEachRemaining(name->{if(!allowed.contains(name))throw new IllegalArgumentException("Unknown field");});return b;}catch(java.io.IOException bad){throw new IllegalArgumentException("Invalid JSON");}}
 private static String text(JsonNode b,String key){if(!b.path(key).isTextual())throw new IllegalArgumentException("Text field required");return b.get(key).textValue();}
 private static long revision(JsonNode b,String key){String value=text(b,key);if(!value.matches("0|[1-9][0-9]{0,18}"))throw new IllegalArgumentException("Exact revision required");try{long n=Long.parseLong(value);if(n==Long.MAX_VALUE)throw new IllegalArgumentException("Exhausted revision");return n;}catch(NumberFormatException bad){throw new IllegalArgumentException("Invalid revision");}}
 private static Actor actor(HttpServletRequest r){return ((ResolvedSession)r.getAttribute(SessionSecurityFilter.SESSION)).actor();}
 private static String key(HttpServletRequest r){var keys=Collections.list(r.getHeaders("Idempotency-Key"));if(keys.size()!=1)throw new IllegalArgumentException("Single original key required");return keys.getFirst();}
 private static void noQuery(HttpServletRequest r){if(!r.getParameterMap().isEmpty())throw new IllegalArgumentException("No query accepted");}
 private static ResponseEntity<?> ok(Object value){return ResponseEntity.ok().header("Cache-Control","private, no-store").body(value);}
}
